def solve(n, m, universe):
    grid = [['.' for _ in range(m)] for _ in range(n)]
    for i, j in enumerate(universe):
        if j == 'X':
            grid[i][0] = 'X'
            grid[i][m - 1] = 'X'
        elif j == '.':
            grid[i][1] = 'X'

    # Calculate distances for each cell from the points on the sides of the rectangle
    dist_to_edges = {}
    for i in range(n*m):
        x = i % m
        y = i // m
        if x == 0 or x == m - 1 or y == 0 or y == n - 1:
            dist_to_edges[i] = grid[x][y]

    # Find the path for each particle
    def bfs(start, end):
        nonlocal grid
        que = deque([(start, [start])])
        visited = set([start])
        while que:
            (x, y), path = que.popleft()
            if x == end:
                return path
            availables = [(r, l) for r in grid[y][x-1:x+2] for l in grid[r - 1:r+2][x] if (r, l) != '.' and (r, l) not in visited]
            for new_x, new_y in availables:
                new_path = path.copy()
                new_path.append((new_x, new_y))
                new_visited = visited | {new_path[-2]}
                queued = False
                for end in new_visited:
                    if end == end:
                        queued = True
                        break
                if not queued:
                    new_dist = grid[new_x - 1][new_y - 1] - grid[x - 1][y - 1]
                    que.append(((new_x, new_y), new_path))
                    dist_to_edges[end] = new_dist
        return None

    max_life = 0
    distribution = [0] * m + [0] * n

    for i in range(m):
        for j in range(n):
            queue = [(j, i)]
            visited = set([(j, i)])
            life = 1  # Assume life starts at 1 for particles starting from the interior
            while queue:
                (x, y), life = queue.pop()
                if x == 0 or x == m - 1 or y == 0 or y == n - 1:
                    distribution[0] = life
                    distribution[0] = life
                    life += 1
                    if life > max_life:
                        max_life = life
                    queue = []
                    break
                else:
                    adjacent_cells = [((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1))]
                    for (dx, dy) in adjacent_cells:
                        if dx in range(n) and dy in range(m) and (dx, dy) not in visited:
                            if dist_to_edges[(x, y)] < dist_to_edges[(dx, dy)]:
                                visited.add(dx, dy)
                                queue.append((dx, dy))
            else:
                max_life = max(max_life, life - 1)

    return max_life / (m * n)

