from heapq import heappush, heappop

def find_intersection(n, m, roads):
    # Create the adjacency list representation of the graph
    graph = {i: [] for i in range(1, n + 1)}
    for u, v in roads:
        graph[u].append(v)

    # Determine the order of the intersections based on the shortest paths from the start to each intersection
    for i in range(1, n + 1):
        distances = {j: float('inf') for j in range(1, n + 1)}
        distances[i] = 0
        visited = {i}
        queue = [(0, i)]

        while queue:
            cur_dist, cur_node = heappop(queue)
            if cur_node in visited:
                continue
            visited.add(cur_node)
            for neighbor in graph[cur_node]:
                if distances[neighbor] > cur_dist + 1:
                    distances[neighbor] = cur_dist + 1
                    heappush(queue, (cur_dist + 1, neighbor))

        # Remove intersections that never get visited to form the final graph
        graph = {i: [] for i in range(1, n + 1)}
        for node in distances:
            if distances[node] == float('inf'):
                continue
            graph[distances[node]].append(node)

    # Check each intersection's path
    for intersection in range(1, n + 1):
        visited = set()
        queue = [(0, intersection)]
        while queue:
            cur_dist, cur_node = heappop(queue)
            if cur_node in visited:
                continue
            visited.add(cur_node)
            for neighbor in graph[cur_node]:
                if neighbor not in visited:
                    heappush(queue, (cur_dist + 1, neighbor))
                if neighbor == intersection:
                    return intersection

    return -1

