import sys

def parse_graph():
    with open(sys.stdin) as file:
        n, m = map(int, file.readline().split())
        edges = [tuple(map(int, line.split())) for line in file.readline().split('\n')[:-1]]
        vertices = [tuple(map(int, line.split())) for line in file.readline().split('\n')[:-1]]
    return n, m, edges, vertices

def query(points, cycle_len, vertices):
    cycle = points[cycle_len % len(points)]
    for i in range(len(cycle)):
        cycle[(i + 1) % len(cycle)] = vertices[vertices.index(cycle[i])]
    connected = set([0])
    next_node = next(iter(connected))
    while next_node != 0:
        for neighbor in cycle[(next_node - 1) % len(cycle) : next_node + 1: -1]:
            if next_node != neighbor:
                connected = connected.union({neighbor})
        next_node = (next_node + 1) % len(cycle)
    return len(connected)

while True:
