def count_binary_numbers(m, n, a00, a01, a10, a11):
    def calculate_proba(a):
        total = 0
        for i in range(2, 11):
            total = (total * 10 % mod + (2 ** (i - 1) - a ** i) % mod) % mod
        return total

    proba = [calculate_proba(i) % mod for i in range(11)]

    dp = [[0] * 4 for _ in range(100001)]  # dp[i][j] represents count of numbers in interval [1, 2^(i-1]] ending with j-digit substring

    for d0 in range(11):
        dp[1][d0] = proba[d0]

    for i in range(2, 1101):
        for j in range(3):
            for k in range(j + 1, min(j + 2, i + 1)):
                if k == j + 1:
                    dp[i][j] = sum(dp[i-k][s] for s in range(j)) % mod
                else:
                    dp[i][j] = sum(dp[i-k][s] for s in range(j + 1, min(j + 2, i + 1))) % mod
                if i - 1 < 11:
                    dp[i][j] = (dp[i][j] + sum(dp[i-2*k+1][s] for s in range(j))) % mod

    exact = sum(dp[n][s]*m**k for s in range(3) for k in range(3))
    for s in range(4):
        exact = (exact + proba[s] * m**4 - dp[n][s]) % mod

    return exact

