def game_tree_operations(n, d, m):
    mod = m
    memo = {}

    def count_possible_moves(n, d):
        if n == 2:
            return 1
        elif n == 3:
            return 6
        else:
            key = tuple((n, d))
            if key not in memo:
                op_choices = []
                for i in range(1, n-1):
                    op_choices.append((i, 'flip', op_choices[i-1], op_choices[i+1]))
                    op_choices.append((i, 'negate', op_choices[i-1], op_choices[i+1]))
                op_choices.append((n-1, 'flip', [k for k in op_choices if k[0]+1 < n-1], op_choices[-1]))
                inp = tuple((np, digit) for digit, np in enumerate(op_choices))
                memo[key] = sum([possible(i) for i in input(inp) if possible(i) != 0]) % mod * mpow(6, n-4, mod) % mod
            return memo[key]

    def possible(i, d):
        arr = [i for i in range(1, n+1)]
        for dl in range(d+1):
            arr = aux_dltion(arr, dl)
        return any(i[j+1] < i[j] for j in range(len(arr)-1))

    def aux_dltion(arr, dl):
        j = dl
        for k in reversed(range(dl, n-dl+1)):
            arr[k] = arr[j]
            j -= 1
        return arr

    def mpow(a, b, m):
        res = 1
        while not b == 0:
            b, x = divmod(b, 2)
            if b == 1:
                res = res * a % m
            a, a = a*a % m, a
        return res

    n = 3  # updated from Input
    d = 1
    return count_possible_moves(n, d)
