def calculate_good_positions(n, k, string):
    good_positions = []
    left = right = 0
    next_good_position = 0

    for i in range(n):
        if i % 2 == 0:
            next_good_position += k
        else:
            next_good_position -= k

        while i - right >= n // 2:
            left += string[right]
            right += 1

        if next_good_position > left:
            diff = next_good_position - left
            right -= 1
            group = 0
            while right - 1 >= 0 and right + 1 < n:
                if string[right] == string[right - 1] == string[right + 1]:
                    group += 3
                elif string[right] == string[right - 1] or string[right] == string[right + 1]:
                    group += 2
                else:
                    group += 1
                right += 1
            diff -= group
            for j in range(i + n // 3, n - n // 3):
                if string[j] != string[j - n // 3] and string[j] != string[j + n // 3]:
                    diff -= 1
            good_positions.append(diff)

    return sum(good_positions)

