import math
from functools import lru_cache

def fibonacci_mod(n, MOD):
    @lru_cache(maxsize=None)
    def fib(n):
        if n == 0: return 0
        elif n == 1: return 1
        else: return (fib(n-1) + fib(n-2)) % MOD
    binaries = []
    orig_n = n
    while True:
        if n > 1 and n % 2 == 0:
            n //= 2
        else: 
            binaries.append(n)
            break
    if len(binaries) != orig_n.bit_length() + 1:
        # if muggles use 1-based indices, shift up.
        n -= 1
    sum_fib = 0
    for n in binaries:
        sum_fib += fib(n) * math.comb(orig_n, n)
    sum_fib %= MOD
    return sum_fib
