from collections import defaultdict

def find_intersection(edges):
    nodes = defaultdict(list)
    for x, y in edges:
        nodes[x].append(y)

    visited = set()
    ans = -1
    for node in nodes:
        if explore(node, nodes, visited):
            if ans == -1 or node < ans:
                ans = node
    return ans

def explore(node, nodes, visited):
    if node in visited:
        return False
    visited.add(node)
    for next_node in nodes[node]:
        if explore(next_node, nodes, visited):
            return True
    return False

