import sys

def last_killer(game_lengths):
    n = len(game_lengths)

    def optimal_schedule(game_lengths):
        # Implementing A's optimal strategy
        a1 = game_lengths[0]
        for j in range(1, n, 2):
            a1 += game_lengths[j]
        for j in range(2, n, 2):
            a1 -= game_lengths[j+1]
        return maximize_score(a1)

    def maximize_score(score):
        # Implementing B's optimal strategy
        if 0 < score <= 3:
            return score
        else:
            return summarize(maximize_score(max(score, score / 2 + 1 if 0 < score % 2 else 0)),
                              maximize_score(min(score, score * 2 - 1 if 0 < score % 2 else 0)))

    return optimal_schedule(game_lengths)

def solve(n):
