from heapq import heappop, heappush
from collections import defaultdict

def dijkstra(graph, start, end):
    distances = {vertex: float('infinity') for vertex in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    used = [False] * len(graph)

    while priority_queue:
        current_distance, current_vertex = heappop(priority_queue)

        if used[current_vertex]:
            continue
        used[current_vertex] = True

        for neighbor, weight in enumerate(graph[current_vertex]):
            if not used[neighbor]:
                edge_weight = current_distance + weight
                if edge_weight < distances[neighbor]:
                    distances[neighbor] = edge_weight
                    heappush(priority_queue, (edge_weight, neighbor))

    if distances[end] == float('infinity'):
        return -1  # Path doesn't exist
    else:
        return distances[end]

def solve():
    n, m = map(int, input().split())
    graph = defaultdict(list)
    used1 = [False] * (n + 1)
    used2 = [False] * (n + 1)

    for _ in range(m):
        u, v, weight = map(int, input().split())
        if not used1[u]:
            graph[u].append(weight)
        if not used2[v]:
            graph[v].append(weight)

        used1[u] = True
        used2[v] = True

    start, end = map(int, input().split())

    result = [dijkstra(graph, start, 0), -1]
    shortest_path_lengths = graph[start]

    if result[1] == -1:
        return result
    else:
        subpath = [0] * shortest_path_lengths
        i = 0
        j = 0
        while min(shortest_path_lengths) > 0:
            if shortest_path_lengths[j] == 0:
                j = j + 1
                continue
            if shortest_path_lengths[j] >= shortest_path_lengths[i]:
                shortest_path_lengths[j] -= 1
                subpath[i] = j
                i = j + 1
            else:
                j = j + 1

    return subpath[:subpath.index(0)] + [end], result[1]

# Running the program
if __name__ == "__main__":
    sol = solve()
    print(sol[1] % 1000000007)
    print(len(sol[0]))
    print(' '.join(map(str, sol[0])))
